def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_aggressive = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 100 or opp.get('budget', 0) >= 500:
                    rich_aggressive += 1

    if not alive:
        return float(min(budget, 18.0))

    units = int(float(supply) // WATER_REQ)
    scarcity = units <= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1

    base = 0.0

    if scarcity:
        if urgency >= 5:
            base = max(118.0, highest_prev + 3.0)
        elif urgency >= 3:
            base = max(92.0, min(116.0, second_prev + 2.5))
        else:
            if highest_prev >= 120:
                base = 24.0
            elif highest_prev >= 90:
                base = 52.0
            else:
                base = max(48.0, highest_prev + 1.5)
    else:
        if urgency >= 5:
            base = max(82.0, second_prev + 2.0)
        elif urgency >= 3:
            base = max(58.0, min(88.0, highest_prev * 0.7))
        else:
            if rich_aggressive >= 2 and highest_prev >= 100:
                base = 18.0
            elif highest_prev >= 100:
                base = 28.0
            else:
                base = max(22.0, second_prev * 0.55)

    remaining_days = max(0, 10 - int(day) + 1)
    soft_cap = budget
    if remaining_days > 0:
        reserve_target = max(0.0, (remaining_days - 1) * 22.0)
        soft_cap = max(0.0, budget - reserve_target)
        if urgency >= 4:
            soft_cap = max(soft_cap, min(budget, 110.0))

    bid = min(budget, base)
    if soft_cap > 0:
        bid = min(bid, max(soft_cap, 16.0 if urgency <= 1 else 30.0))

    if urgency >= 5:
        bid = max(bid, min(budget, 95.0 if not scarcity else 120.0))
    elif urgency >= 3:
        bid = max(bid, min(budget, 60.0 if not scarcity else 90.0))

    if budget < 35:
        bid = min(bid, budget)
        if urgency <= 1:
            bid = min(bid, 20.0)

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', (MIN_SUPPLY + MAX_SUPPLY) / 2.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for k, o in opponents_status.items():
        if o is not None and bool(o.get('alive', False)):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids
    yesterday_bids = []
    yesterday_by_agent = {}
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
            except Exception:
                continue
            yesterday_bids.append(b_val)
            yesterday_by_agent[opp.get('agent_id', None)] = b_val

    # If we can't read bids, fall back to survival-oriented bidding
    if not yesterday_bids:
        if hp <= 2 or no_water_days >= 1:
            return max(0.0, min(budget, DAILY_SALARY * 0.85))
        return max(0.0, min(budget, DAILY_SALARY * 0.55))

    highest_prev_bid = max(yesterday_bids)
    # Identify Cindy's likely pressure if present
    cindy_bid = None
    for opp in alive_opps:
        if opp.get('agent_id', None) == 'Cindy':
            prev = opp.get('previous_trace', {}) or {}
            if prev.get('bid', None) is not None:
                try:
                    cindy_bid = float(prev.get('bid'))
                except Exception:
                    cindy_bid = None

    # Estimate how many water units we can reasonably target
    # supply is total available; bidding competition determines allocation.
    # We aim to secure at least our requirement when supply is closer to MIN.
    supply_ratio = supply / float(WATER_REQ)
    # If supply is barely above our requirement, we must prioritize.
    scarcity = 1.0
    if supply_ratio >= 2.0:
        scarcity = 0.7
    elif supply_ratio >= 1.5:
        scarcity = 0.85

    # Pressure response: if someone paid near/above our daily salary, we should not underbid too much.
    pressure = 0.0
    if cindy_bid is not None:
        pressure = cindy_bid
    else:
        pressure = highest_prev_bid

    # Base bid level
    if hp <= 2 or no_water_days >= 2:
        base = DAILY_SALARY * 0.95
    elif hp <= 4 or no_water_days >= 1:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.58

    # Adjust with yesterday pressure
    # If Cindy/highest_prev_bid was high, increase slightly to avoid losing allocation.
    # Otherwise, keep moderate to preserve budget.
    if pressure >= DAILY_SALARY * 1.25:
        base *= 1.05
    elif pressure >= DAILY_SALARY * 0.9:
        base *= 1.0
    else:
        base *= 0.92

    # Scarcity adjustment
    base *= scarcity

    # Practical cap: we never bid above budget or a fraction of remaining days' ability.
    # With episode_days=10, a conservative cap helps avoid running out.
    episode_days = int(getattr(day_context, 'episode_days', 10) if hasattr(day_context, 'episode_days') else 10)
    # day_context does not include episode_days; use 10 as default.
    # Avoid using non-provided fields.
    remaining_days = 10 - int(day) if isinstance(day, (int, float)) else 10
    if remaining_days < 1:
        remaining_days = 1
    daily_cap = DAILY_SALARY * 0.95
    cap = min(budget, daily_cap)

    bid = max(0.0, min(cap, base))

    # Small anti-tying/underbidding nudge: if highest_prev_bid was not too far above our base, bid slightly above it.
    # Use int() indices only if needed; here no indexing.
    if highest_prev_bid > 0:
        if bid < highest_prev_bid * 0.98:
            bid = min(cap, highest_prev_bid * 1.02)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    my_hp = int(my_status['hp'])
    my_budget = my_status['budget']
    no_water = int(my_status['no_water_days'])
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])
    max_prev_bid = max(prev_bids) if prev_bids else 0.0
    supply_per_player = supply / (len(alive_opponents) + 1) if alive_opponents else supply
    base_need = my_hp <= 3 or no_water >= 1
    if my_hp <= 2:
        # desperate: need water badly
        bid = min(my_budget, DAILY_SALARY * 1.1)
    elif my_hp <= 4:
        # moderate risk
        if max_prev_bid > DAILY_SALARY * 0.85 and supply_per_player >= WATER_REQ:
            bid = min(my_budget, DAILY_SALARY * 0.6)
        else:
            bid = min(my_budget, DAILY_SALARY * 0.9)
    else:
        # healthy: can afford to lose a day
        if max_prev_bid > DAILY_SALARY * 0.85:
            bid = min(my_budget, DAILY_SALARY * 0.4)
        else:
            bid = min(my_budget, DAILY_SALARY * 0.65)
    # Ensure minimum bid to not waste budget if bid is very low
    if bid < 10 and my_budget > 10:
        bid = 10
    return float(bid)
